Value.Calculation:
Let (
  fn = GetContainerAttribute ( _globals::Logo ; "filename" ) ;
  Lower ( RightWords ( Substitute ( fn ; "." ; " " ) ; 1 ) )
)

If ( $hasLogo ;
  While (
    [ s = Base64EncodeRFC ( 4648 ; _globals::Logo ) ; out = "" ] ;
    Length ( s ) > 0 ;
    [ out = out & Left ( s ; 76 ) & ¶ ; s = Middle ( s ; 77 ; Length ( s ) ) ] ;
    out
  ) ;
  ""
)

If ( $hasLogo ;
  Let ( [
    w = GetAsNumber ( GetContainerAttribute ( _globals::Logo ; "width" ) ) ;
    h = GetAsNumber ( GetContainerAttribute ( _globals::Logo ; "height" ) ) ;
    dispW = If ( w > 0 ; Min ( 180 ; w ) ; 180 ) ;
    dispH = If ( w > 0 and h > 0 ; Round ( dispW * h / w ; 0 ) ; 0 )
  ] ;
    "<tr><td style='padding:20px 32px;background:#ffffff;'>" &
    "<img src='cid:mcslogo' alt='MC Services' width='" & dispW & "'" &
    If ( dispH > 0 ; " height='" & dispH & "'" ; "" ) &
    " style='display:block;border:0;'></td></tr>" & ¶
  ) ;
  ""
)

Step.Calculation:
JSONSetElement ( "{}" ;
  [ "ok" ; 0 ; JSONNumber ] ;
  [ "error" ; "No recipient email address was passed to the server script." ; JSONString ]
)

JSONSetElement ( "{}" ;
  [ "ok" ; 0 ; JSONNumber ] ;
  [ "error" ; "The mail settings in _globals are empty on the server. Open the file locally, enter them, close it and upload it again." ; JSONString ]
)

JSONSetElement ( "{}" ;
  [ "ok" ; 0 ; JSONNumber ] ;
  [ "error" ; "Could not send the survey results to " & $to & ". FileMaker error: " & If ( IsEmpty ( $error ) ; "(not captured)" ; GetValue ( $error ; 1 ) ) ; JSONString ] ;
  [ "detail" ; GetValue ( $error ; 2 ) ; JSONString ]
)
